<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TagContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: TagContract  = $props();
const uid=$props.id();let root=$state<HTMLDivElement>();let list=$state<HTMLUListElement>();let active=$state(untrack(()=>p.items.find(x=>!x.disabled)?.id));function targets(){return [...root!.querySelectorAll<HTMLElement>('[data-tag-action]')].filter(x=>!x.matches(':disabled'));}function key(e:KeyboardEvent){if(ignoredKey(e)||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=targets(),i=list.indexOf(document.activeElement as HTMLElement),next=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;active=list[next]?.dataset.tagAction;list[next]?.focus();}async function remove(id:string){const index=p.items.findIndex(x=>x.id===id);p.onRemove?.({id});await tick();if(p.items.some(x=>x.id===id))return;const next=p.items.slice(0,index).reverse().find(x=>!x.disabled)??p.items.find(x=>!x.disabled);active=next?.id;(targets().find(x=>x.dataset.tagAction===next?.id)??list)?.focus();}async function add(id:string){p.onAdd?.({id});await tick();document.getElementById(p.appliedBarId??'')?.focus();}function select(id:string){const ids=p.selectedIds??[];p.onSelectionChange?.({ids:ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]});}
$effect.pre(()=>{const enabled=p.items.filter(item=>!item.disabled);if(enabled.some(item=>item.id===active))return;const ownedFocus=root?.contains(document.activeElement)??false;active=enabled[0]?.id;if(ownedFocus)void tick().then(()=>{(targets().find(node=>node.dataset.tagAction===active)??list)?.focus();});});
</script>
<div bind:this={root} role={p.mode&&p.mode!=='static'?'group':undefined} aria-label={p.mode&&p.mode!=='static'?'옵션 태그':undefined} {...owned('tag','root')} data-krds-mode={p.mode??'static'}><!-- svelte-ignore a11y_no_noninteractive_element_interactions (Arrow keys move the roving tab stop between the list's own controls.) -->
<ul bind:this={list} tabindex="-1" {...owned('tag','list')} onkeydown={key}>{#each p.items as item(item.id)}<li {...owned('tag','item',p.selectedIds?.includes(item.id)&&'selected')}>{#if p.mode==='link'}<a id={`${uid}-${item.id}`} href={item.disabled?undefined:item.href} aria-disabled={item.disabled||undefined} data-tag-action={item.disabled?undefined:item.id} tabindex={!item.disabled&&active===item.id?0:-1} onfocus={()=>active=item.id}>{item.label}</a>{:else if p.mode==='toggle'||p.mode==='add-filter'}<button id={`${uid}-${item.id}`} type="button" {...owned('tag','label')} disabled={item.disabled} data-tag-action={item.id} tabindex={!item.disabled&&active===item.id?0:-1} onfocus={()=>active=item.id} aria-pressed={p.mode==='toggle'?p.selectedIds?.includes(item.id)??false:undefined} aria-label={p.mode==='add-filter'?`${item.label} 필터 옵션 추가`:undefined} onclick={()=>p.mode==='toggle'?select(item.id):add(item.id)}>{item.label}</button>{:else}<span {...owned('tag','label')}>{item.label}</span>{#if p.mode==='removable'}<button id={`${uid}-${item.id}`} type="button" {...owned('tag','remove')} disabled={item.disabled} data-tag-action={item.id} tabindex={!item.disabled&&active===item.id?0:-1} onfocus={()=>active=item.id} aria-label={`${item.label} 옵션 삭제`} onclick={()=>remove(item.id)}>×</button>{/if}{/if}</li>{/each}</ul>{#if p.onClear&&p.items.length&&['toggle','removable','add-filter'].includes(p.mode??'static')}<button type="button" {...owned('tag','clear')} onclick={()=>p.onClear?.()}>전체 삭제</button>{/if}</div>
